function theme_toggle(): string {
    return '<button class="theme-toggle" type="button" role="switch" aria-checked="false" data-theme-toggle aria-label="Modo escuro" title="Alternar modo claro / escuro">'
        . '<span class="tt-opt tt-light">' . icon('sun') . '</span>'
        . '<span class="tt-opt tt-dark">' . icon('moon') . '</span>'
        . '<span class="tt-knob"></span>'
        . '</button>';
}

function brand_mark(): string {
    return '<span class="dot">' . icon('check') . '</span>';
}
